/*!
 * netioConnector.js - NetIO Socket.IO Client Connector
 * Connects to netio-runner microservice via Socket.IO
 */

const debug = require('debug')('mutech:netio-connector');

class NetioConnector {
  constructor(io, db) {
    this.io = io;
    this.db = db;
    this.type = 'netio';

    // Connection state
    this.isRunnerConnected = false;
    this.runnerSocket = null;

    // Configuration
    this.requestTimeout = 10000; // 10 seconds

    this.setupNetioNamespace();

    debug('NetIO Connector initialized, waiting for runner connection');
  }

  setupNetioNamespace() {
    // Setup namespace for netio-runner to connect to
    this.netioNamespace = this.io.of('/runner-netio');

    this.netioNamespace.on('connection', (socket) => {
      this.isRunnerConnected = true;
      this.runnerSocket = socket;
      debug('NetIO runner connected: %s', socket.id);

      // Emit debug event
      this.emitDebugEvent('runner_connected', {
        runnerId: socket.id,
        timestamp: Date.now()
      });

      socket.on('disconnect', () => {
        this.isRunnerConnected = false;
        this.runnerSocket = null;
        debug('NetIO runner disconnected: %s', socket.id);

        // Emit debug event
        this.emitDebugEvent('runner_disconnected', {
          runnerId: socket.id,
          timestamp: Date.now()
        });
      });
    });
  }

  async getState(unit) {
    const startTime = Date.now();

    try {
      debug('Getting state for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'NetIO runner not connected';
        debug('getState failed: %s', error);
        return {
          success: false,
          state: -1,
          error: error,
          unitType: this.type
        };
      }

      // Build request
      const request = {
        ip: this.getHostForUnit(unit),
        port: parseInt(unit.args?.port || '0'),
        options: this.getOptionsForUnit(unit)
      };

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('getState', request);

      if (response.success) {
        // API returns all ports, find our port
        const portData = response.data.find(p => p.port === request.port);
        const state = portData ? (portData.state === 'on' ? 1 : 0) : -1;

        debug('getState success for unit: %s, state: %d', unit.id, state);

        return {
          success: true,
          state: state,
          unitType: this.type,
          host: request.ip,
          port: request.port,
          timestamp: Date.now()
        };
      } else {
        debug('getState failed for unit: %s, error: %s', unit.id, response.error);
        return {
          success: false,
          state: -1,
          error: response.error,
          unitType: this.type
        };
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      debug('getState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);

      return {
        success: false,
        state: -1,
        error: error.message,
        unitType: this.type
      };
    }
  }

  async setState(unit, targetState) {
    const startTime = Date.now();

    try {
      const stateStr = targetState ? 'on' : 'off';
      debug('Setting state for unit: %s (%s) to %s', unit.id, this.getHostForUnit(unit), stateStr);

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'NetIO runner not connected';
        debug('setState failed: %s', error);
        return {
          success: false,
          state: unit.state, // Keep current state
          error: error,
          unitType: this.type
        };
      }

      // Build request
      const request = {
        ip: this.getHostForUnit(unit),
        port: parseInt(unit.args?.port || '0'),
        state: stateStr,
        options: this.getOptionsForUnit(unit)
      };

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('setState', request);

      if (response.success) {
        const finalState = targetState ? 1 : 0;
        debug('setState success for unit: %s, state: %d, duration: %dms', unit.id, finalState, response.duration || 0);

        return {
          success: true,
          state: finalState,
          unitType: this.type,
          host: request.ip,
          port: request.port,
          duration: response.duration,
          timestamp: Date.now()
        };
      } else {
        debug('setState failed for unit: %s, error: %s', unit.id, response.error);
        return {
          success: false,
          state: unit.state, // Keep current state on failure
          error: response.error,
          unitType: this.type
        };
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      debug('setState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);

      return {
        success: false,
        state: unit.state, // Keep current state on failure
        error: error.message,
        unitType: this.type
      };
    }
  }

  // Test connection to a NetIO device
  async testConnection(unit) {
    try {
      debug('Testing connection for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      if (!this.isRunnerConnected || !this.runnerSocket) {
        return {
          success: false,
          error: 'NetIO runner not connected'
        };
      }

      const request = {
        ip: this.getHostForUnit(unit),
        options: this.getOptionsForUnit(unit)
      };

      const response = await this.sendRequestWithTimeout('testConnection', request);

      debug('testConnection result for unit: %s, connected: %s', unit.id, response.success ? response.data?.connected : 'failed');

      return response;

    } catch (error) {
      debug('testConnection exception for unit: %s, error: %s', unit.id, error.message);
      return {
        success: false,
        error: error.message
      };
    }
  }

  // Get device information
  async getDeviceInfo(unit) {
    try {
      debug('Getting device info for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      if (!this.isRunnerConnected || !this.runnerSocket) {
        return {
          success: false,
          error: 'NetIO runner not connected'
        };
      }

      const request = {
        ip: this.getHostForUnit(unit),
        options: this.getOptionsForUnit(unit)
      };

      const response = await this.sendRequestWithTimeout('getDeviceInfo', request);

      debug('getDeviceInfo result for unit: %s, success: %s', unit.id, response.success);

      return response;

    } catch (error) {
      debug('getDeviceInfo exception for unit: %s, error: %s', unit.id, error.message);
      return {
        success: false,
        error: error.message
      };
    }
  }

  // Send request to runner with timeout
  sendRequestWithTimeout(event, data) {
    return new Promise((resolve, reject) => {
      if (!this.runnerSocket) {
        reject(new Error('NetIO runner not connected'));
        return;
      }

      // Set timeout
      const timeoutId = setTimeout(() => {
        debug('Request timeout for event: %s, data: %o', event, data);
        this.emitDebugEvent('request_timeout', {
          event: event,
          data: data,
          timeout: this.requestTimeout,
          timestamp: Date.now()
        });
        reject(new Error(`Timeout waiting for NetIO runner response (${this.requestTimeout}ms)`));
      }, this.requestTimeout);

      // Send request
      this.runnerSocket.emit(event, data, (response) => {
        clearTimeout(timeoutId);

        if (!response) {
          reject(new Error('No response from NetIO runner'));
          return;
        }

        // Pass through response as-is
        resolve(response);
      });
    });
  }

  // Get host for unit (unit.host first, fallback to unit.ip)
  getHostForUnit(unit) {
    if (unit.host && unit.host !== '#nohost') {
      return unit.host;
    }
    return unit.ip || 'unknown-host';
  }

  // Get options for unit (auth, timeout, etc.)
  getOptionsForUnit(unit) {
    const options = {};

    // Add authentication if available in unit args
    if (unit.args?.user) {
      options.user = unit.args.user;
    }
    if (unit.args?.password) {
      options.password = unit.args.password;
    }

    // Add timeout if specified in unit args
    if (unit.args?.timeout) {
      options.timeout = parseInt(unit.args.timeout);
    }

    return options;
  }

  // Emit debug event to debug namespace
  emitDebugEvent(eventType, data) {
    try {
      this.io.of('/debug').emit('netioEvent', {
        type: eventType,
        data: data,
        timestamp: Date.now()
      });
    } catch (error) {
      // Don't let debug event emission fail the main operation
      debug('Error emitting debug event: %s', error.message);
    }
  }

  // Check if runner is connected
  isConnected() {
    return this.isRunnerConnected;
  }

  // Get connector information
  getConnectorInfo() {
    return {
      type: this.type,
      status: this.isRunnerConnected ? 'connected' : 'waiting',
      capabilities: ['getState', 'setState', 'testConnection', 'getDeviceInfo'],
      description: 'NetIO Socket.IO connector - communicates with netio-runner microservice',
      runnerConnected: this.isRunnerConnected,
      requestTimeout: this.requestTimeout,
      method: 'socket.io-client'
    };
  }

  // Disconnect (cleanup)
  disconnect() {
    debug('NetIO Connector disconnecting');

    if (this.netioNamespace) {
      // Close namespace connections
      this.netioNamespace.disconnectSockets(true);
    }

    this.isRunnerConnected = false;
    this.runnerSocket = null;
  }
}

module.exports = NetioConnector;

