/*!
 * projectorConnector.js - PJLink Socket.IO Client Connector
 * Connects to pjlink-runner microservice via Socket.IO
 */

const debug = require('debug')('mutech:projector-connector');

class ProjectorConnector {
  constructor(io, db) {
    this.io = io;
    this.db = db;
    this.type = 'projector';

    // Connection state
    this.isRunnerConnected = false;
    this.runnerSocket = null;

    // Configuration - projectors are slower than other devices
    this.requestTimeout = 15000; // 15 seconds for slow projectors

    this.setupProjectorNamespace();

    debug('Projector Connector initialized, waiting for runner connection');
  }

  setupProjectorNamespace() {
    // Setup namespace for pjlink-runner to connect to
    this.projectorNamespace = this.io.of('/runner-pjlink');

    this.projectorNamespace.on('connection', (socket) => {
      this.isRunnerConnected = true;
      this.runnerSocket = socket;
      debug('PJLink runner connected: %s', socket.id);

      // Emit debug event
      this.emitDebugEvent('runner_connected', {
        runnerId: socket.id,
        timestamp: Date.now()
      });

      socket.on('disconnect', () => {
        this.isRunnerConnected = false;
        this.runnerSocket = null;
        debug('PJLink runner disconnected: %s', socket.id);

        // Emit debug event
        this.emitDebugEvent('runner_disconnected', {
          runnerId: socket.id,
          timestamp: Date.now()
        });
      });
    });
  }

  async getState(unit) {
    const startTime = Date.now();

    try {
      debug('Getting state for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'PJLink runner not connected';
        debug('getState failed: %s', error);
        return {
          success: false,
          state: -1,
          error: error,
          unitType: this.type
        };
      }

      // Build request
      const request = {
        unitId: unit.id,
        operation: 'getState',
        ip: this.getHostForUnit(unit),
        password: unit.args?.password || '',
        timeout: 10000 // 10 seconds for state queries
      };

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('executeCommand', request);

      if (response.success) {
        debug('getState success for unit: %s, state: %d (%s)', unit.id, response.state, this.getStateDescription(response.state));

        return {
          success: true,
          state: response.state,
          unitType: this.type,
          host: request.ip,
          stateDescription: this.getStateDescription(response.state),
          lampHours: response.lampHours,
          temperature: response.temperature,
          timestamp: Date.now()
        };
      } else {
        debug('getState failed for unit: %s, error: %s', unit.id, response.error);
        return {
          success: false,
          state: -1,
          error: response.error,
          unitType: this.type
        };
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      debug('getState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);

      return {
        success: false,
        state: -1,
        error: error.message,
        unitType: this.type
      };
    }
  }

  async setState(unit, targetState) {
    const startTime = Date.now();

    try {
      const stateStr = targetState ? 'on' : 'off';
      debug('Setting state for unit: %s (%s) to %s', unit.id, this.getHostForUnit(unit), stateStr);

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'PJLink runner not connected';
        debug('setState failed: %s', error);
        return {
          success: false,
          state: unit.state, // Keep current state
          error: error,
          unitType: this.type
        };
      }

      // Build request
      const request = {
        unitId: unit.id,
        operation: 'setState',
        ip: this.getHostForUnit(unit),
        targetState: targetState ? 1 : 0,
        state: stateStr,
        password: unit.args?.password || '',
        timeout: 12000 // 12 seconds for power commands (projectors can be slow)
      };

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('executeCommand', request);

      if (response.success) {
        // Note: Projectors may return intermediate states (warming/cooling)
        const responseState = response.state !== undefined ? response.state : (targetState ? 1 : 0);
        debug('setState success for unit: %s, state: %d (%s), duration: %dms', 
              unit.id, responseState, this.getStateDescription(responseState), response.duration || 0);

        return {
          success: true,
          state: responseState,
          unitType: this.type,
          host: request.ip,
          stateDescription: this.getStateDescription(responseState),
          duration: response.duration,
          timestamp: Date.now()
        };
      } else {
        debug('setState failed for unit: %s, error: %s', unit.id, response.error);
        return {
          success: false,
          state: unit.state, // Keep current state on failure
          error: response.error,
          unitType: this.type
        };
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      debug('setState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);

      return {
        success: false,
        state: unit.state, // Keep current state on failure
        error: error.message,
        unitType: this.type
      };
    }
  }

  // Get projector information (lamp hours, temperature, model, etc.)
  async getProjectorInfo(unit) {
    try {
      debug('Getting projector info for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      if (!this.isRunnerConnected || !this.runnerSocket) {
        return {
          success: false,
          error: 'PJLink runner not connected'
        };
      }

      const request = {
        unitId: unit.id,
        operation: 'getProjectorInfo',
        ip: this.getHostForUnit(unit),
        password: unit.args?.password || '',
        timeout: 8000
      };

      const response = await this.sendRequestWithTimeout('executeCommand', request);

      debug('getProjectorInfo result for unit: %s, success: %s', unit.id, response.success);

      return response;

    } catch (error) {
      debug('getProjectorInfo exception for unit: %s, error: %s', unit.id, error.message);
      return {
        success: false,
        error: error.message
      };
    }
  }

  // Test projector connection
  async testConnection(unit) {
    try {
      debug('Testing connection for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      if (!this.isRunnerConnected || !this.runnerSocket) {
        return {
          success: false,
          error: 'PJLink runner not connected'
        };
      }

      const request = {
        unitId: unit.id,
        operation: 'testConnection',
        ip: this.getHostForUnit(unit),
        password: unit.args?.password || '',
        timeout: 5000
      };

      const response = await this.sendRequestWithTimeout('executeCommand', request);

      debug('testConnection result for unit: %s, connected: %s', unit.id, response.success);

      return response;

    } catch (error) {
      debug('testConnection exception for unit: %s, error: %s', unit.id, error.message);
      return {
        success: false,
        error: error.message
      };
    }
  }

  // Send request to runner with timeout
  sendRequestWithTimeout(event, data) {
    return new Promise((resolve, reject) => {
      if (!this.runnerSocket) {
        reject(new Error('PJLink runner not connected'));
        return;
      }

      // Set timeout
      const timeoutId = setTimeout(() => {
        debug('Request timeout for event: %s, data: %o', event, data);
        this.emitDebugEvent('request_timeout', {
          event: event,
          data: data,
          timeout: this.requestTimeout,
          timestamp: Date.now()
        });
        reject(new Error(`Timeout waiting for PJLink runner response (${this.requestTimeout}ms)`));
      }, this.requestTimeout);

      // Send request
      this.runnerSocket.emit(event, data, (response) => {
        clearTimeout(timeoutId);

        if (!response) {
          reject(new Error('No response from PJLink runner'));
          return;
        }

        // Pass through response as-is
        resolve(response);
      });
    });
  }

  // Get host for unit (unit.host first, fallback to unit.ip)
  getHostForUnit(unit) {
    if (unit.host && unit.host !== '#nohost') {
      return unit.host;
    }
    return unit.ip || 'unknown-host';
  }

  // Get human-readable state description
  getStateDescription(state) {
    switch (state) {
      case -1: return 'offline/error';
      case 0: return 'off';
      case 1: return 'on';
      case 2: return 'cooling';
      case 3: return 'warming';
      default: return 'unknown';
    }
  }

  // Emit debug event to debug namespace
  emitDebugEvent(eventType, data) {
    try {
      this.io.of('/debug').emit('projectorEvent', {
        type: eventType,
        data: data,
        timestamp: Date.now()
      });
    } catch (error) {
      // Don't let debug event emission fail the main operation
      debug('Error emitting debug event: %s', error.message);
    }
  }

  // Check if runner is connected
  isConnected() {
    return this.isRunnerConnected;
  }

  // Get connector information
  getConnectorInfo() {
    return {
      type: this.type,
      status: this.isRunnerConnected ? 'connected' : 'waiting',
      capabilities: ['getState', 'setState', 'getProjectorInfo', 'testConnection'],
      description: 'PJLink Socket.IO connector - communicates with pjlink-runner microservice',
      runnerConnected: this.isRunnerConnected,
      requestTimeout: this.requestTimeout,
      method: 'socket.io-client',
      protocol: 'PJLink via modernized library',
      supportedStates: {
        '-1': 'offline/error',
        '0': 'off',
        '1': 'on', 
        '2': 'cooling',
        '3': 'warming'
      },
      projectorFeatures: ['lamp hours', 'temperature monitoring', 'power state management']
    };
  }

  // Disconnect (cleanup)
  disconnect() {
    debug('Projector Connector disconnecting');

    if (this.projectorNamespace) {
      // Close namespace connections
      this.projectorNamespace.disconnectSockets(true);
    }

    this.isRunnerConnected = false;
    this.runnerSocket = null;
  }
}

module.exports = ProjectorConnector;

