/**
 * NetIO Runner - Main Application Entry Point
 * 
 * @author Marc Schütze
 * @license GPL-3.0
 */

// Load environment configuration
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

const debug = require('debug')('runner:main');
const io = require('socket.io-client');
const SocketHandler = require('./socketHandler');
const config = require('./config');
const { setupErrorTransport } = require('./errorTransport');

class NetIORunner {
  constructor() {
    this.errorSocket = null;
    this.mainSocket = null;
    this.socketHandler = null;
    this.isShuttingDown = false;
    debug('NetIORunner instance created');
  }

  async start() {
    debug('Starting NetIO Runner');
    debug('Main server URL: %s', config.MAIN_SERVER_URL);

    this.setupProcessHandlers();
    await this.setupErrorTransport();
    await this.connectToMainServer();

    debug('NetIO Runner started successfully');
  }

  async setupErrorTransport() {
    debug('Setting up error transport to %s/debug', config.MAIN_SERVER_URL);

    this.errorSocket = io(`${config.MAIN_SERVER_URL}/debug`, {
      reconnection: true,
      reconnectionDelay: 2000,
      reconnectionDelayMax: 10000,
      reconnectionAttempts: Infinity,
      randomizationFactor: 0.5,
      transports: ['websocket', 'polling']
    });

    this.errorSocket.on('connect', () => {
      debug('Error transport connected');
      setupErrorTransport(this.errorSocket);
    });

    this.errorSocket.on('disconnect', (reason) => {
      debug('Error transport disconnected: %s', reason);
      if (reason === 'io server disconnect') {
        debug('Error transport disconnected by server');
      }
    });

    this.errorSocket.on('connect_error', (error) => {
      debug('Error transport connection failed: %s', error.message);
    });

    await new Promise(resolve => setTimeout(resolve, 1000));
    debug('Error transport setup complete');
  }

  async connectToMainServer() {
    debug('Connecting to main server at %s/runner-netio', config.MAIN_SERVER_URL);

    this.mainSocket = io(`${config.MAIN_SERVER_URL}/runner-netio`, {
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 30000,
      reconnectionAttempts: Infinity,
      randomizationFactor: 0.5,
      timeout: config.NETIO_CONNECTION_TIMEOUT,
      transports: ['websocket', 'polling']
    });

    this.socketHandler = new SocketHandler();
    this.socketHandler.setupHandlers(this.mainSocket);

    this.mainSocket.on('connect', () => {
      debug('Connected to main server with ID: %s', this.mainSocket.id);
    });

    this.mainSocket.on('disconnect', (reason) => {
      debug('Main server disconnected: %s', reason);
      if (reason === 'io server disconnect') {
        debug('Main server disconnected - will reconnect automatically');
      }
    });

    this.mainSocket.on('connect_error', (error) => {
      debug('Main server connection failed - retrying: %s', error.message);
    });

    this.mainSocket.on('reconnect', (attemptNumber) => {
      debug('Reconnected to main server (attempt %d)', attemptNumber);
    });

    debug('Main server connection setup complete');
  }

  setupProcessHandlers() {
    debug('Setting up process signal handlers');

    const shutdown = async (signal) => {
      if (this.isShuttingDown) {
        debug('Shutdown already in progress, ignoring %s', signal);
        return;
      }
      debug('Received %s, shutting down gracefully...', signal);
      this.isShuttingDown = true;

      try {
        if (this.socketHandler) {
          debug('Shutting down socket handler...');
          await this.socketHandler.shutdown();
        }

        if (this.mainSocket) {
          debug('Disconnecting main socket...');
          this.mainSocket.disconnect();
        }

        if (this.errorSocket) {
          debug('Disconnecting error socket...');
          this.errorSocket.disconnect();
        }

        debug('NetIO Runner shutdown complete');
        process.exit(0);
      } catch (error) {
        debug('Error during shutdown: %s', error.message);
        process.exit(1);
      }
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));
    process.on('SIGHUP', () => shutdown('SIGHUP'));

    process.on('uncaughtException', async (error) => {
      debug('Uncaught exception: %s', error.message);
      if (this.isFatalSystemError(error)) {
        debug('Fatal system error detected - shutting down');
        await shutdown('UNCAUGHT_EXCEPTION');
      }
    });

    process.on('unhandledRejection', async (reason, promise) => {
      debug('Unhandled promise rejection: %s', reason?.message || reason);
      if (reason && this.isFatalSystemError(reason)) {
        debug('Fatal promise rejection - shutting down');
        await shutdown('UNHANDLED_REJECTION');
      }
    });

    debug('Process handlers setup complete');
  }

  isFatalSystemError(error) {
    const fatalConditions = [
      error.code === 'ENOMEM',
      error.code === 'ENOSPC',
      error.code === 'EMFILE',
      error.code === 'ENFILE',
      error.message?.includes('Maximum call stack size exceeded'),
      error.message?.includes('out of memory'),
      error.code === 'EACCES' && error.message?.includes('Permission denied')
    ];
    const isFatal = fatalConditions.some(condition => condition === true);
    debug('Checking if error is fatal: %s (result: %s)', error.code || error.message, isFatal);
    return isFatal;
  }

  getConnectionStatus() {
    const status = {
      mainSocket: {
        connected: this.mainSocket?.connected || false,
        id: this.mainSocket?.id
      },
      errorSocket: {
        connected: this.errorSocket?.connected || false,
        id: this.errorSocket?.id
      },
      isShuttingDown: this.isShuttingDown
    };
    debug('Connection status: %o', status);
    return status;
  }
}

if (require.main === module) {
  const runner = new NetIORunner();
  runner.start().catch((error) => {
    debug('Failed to start runner: %s', error.message);
  });
}

module.exports = NetIORunner;

