    e.preventDefault();
    socket.emit("changeState", { object: object, state: state });
  };
  return (
    <ButtonGroup className="float-end" size="sm">
      <Button
        size="sm"
        variant="secondary"
        id={"exhibitOnButton" + object.id}
        key={"exhibitOnButton" + object.id}
        onClick={(e) => {
          submitEvent(e, object, 1);
        }}
      >
        On
      </Button>
      <Button
        size="sm"
        variant="danger"
        id={"exhibitOffButton" + object.id}
        key={"exhibitOffButton" + object.id}
        onClick={(e) => {
          submitEvent(e, object, 0);
        }}
      >
        Off
      </Button>
    </ButtonGroup>
  );
}

export default ButtonsOnOff;

