import React, { useState } from "react";
import {
  Card,
  Form,
  Button,
  ButtonGroup,
  InputGroup,
  ToggleButton,
} from "react-bootstrap";

function FormNetio({ socket, parentObject, handleModalClose }) {
  const initialFormState = {
    host: "",
    netioPortRadio: "0",
    name: "",
    automation: true,
  };

  const [FormState, setFormState] = useState(initialFormState);

  const handleInputChange = (e) => {
    setFormState((previousState) => {
      return { ...previousState, [e.target.name]: e.target.value.trim().replace("http://", "") };
    });
  };
  const handleCheckboxChange = (e) => {
    setFormState((previousState) => {
      return { ...previousState, [e.target.name]: e.target.checked };
    });
  };
  const handleSubmit = (e) => {
    e.preventDefault();
    if (FormState.host.length < 3) {
      console.log("to short");
    } else {
      addUnit();
      if (e.target.id === "saveAndAddNew") {
        setFormState(initialFormState);
      } else {
        handleModalClose();
      }
    }
  };

  const addUnit = () => {
    const unit = {
      parentId: parentObject.id,
      host: FormState.host.toLowerCase(),
      unitType: "netio",
      type: "unit",
      automation: FormState.automation,
      args: {
        port: FormState.netioPortRadio,
        name: FormState.name,
      },
    };
    socket.emit("command", {
      cmd: "add",
      data: unit,
    });
  };

  return (
    <Card>
      <Card.Header>Add New NETIO</Card.Header>
      <Card.Body>
        <Form>
          <InputGroup className="mb-3">
            <InputGroup.Text style={{ width: "100px" }}>Host</InputGroup.Text>
            <Form.Control
              name="host"
              placeholder="Host / IP"
              onChange={handleInputChange}
              value={FormState.host}
            />
          </InputGroup>
          <InputGroup className="mb-3">
            <InputGroup.Text style={{ width: "100px" }}>Name</InputGroup.Text>

            <Form.Control
              name="name"
              onChange={handleInputChange}
              value={FormState.name}
              placeholder="name (Leave blank for NO name)"
            />
          </InputGroup>
          <div className="row">
            <ButtonGroup className="mb-2">
              {[0, 1, 2].map((radio) => (
                <ToggleButton
                  key={radio}
                  id={`netioPortRadio-${radio}`}
                  type="radio"
                  variant="secondary"
                  name="netioPortRadio"
                  value={radio}
                  checked={FormState.netioPortRadio === "" + radio} // make radio a string... because fuck you react
                  onChange={handleInputChange}
                >
                  Port {radio + 1}
                </ToggleButton>
              ))}
            </ButtonGroup>
          </div>
          <div>
            <Form.Check
              name="automation"
              type="switch"
              id="custom-switch"
              label="Automatic"
              onChange={handleCheckboxChange}
              checked={FormState.automation}
            />
          </div>
          <ButtonGroup>
            <Button type="submit" id="saveAndAddNew" onClick={handleSubmit}>
              Submit & Add new
