     1→/*!
     2→ * anelConnector.js - ANEL Socket.IO Client Connector
     3→ * Connects to anel-runner microservice via Socket.IO
     4→ */
     5→
     6→const debug = require('debug')('mutech:anel-connector');
     7→
     8→class AnelConnector {
     9→  constructor(io, db) {
    10→    this.io = io;
    11→    this.db = db;
    12→    this.type = 'anel';
    13→
    14→    // Connection state
    15→    this.isRunnerConnected = false;
    16→    this.runnerSocket = null;
    17→
    18→    // Configuration
    19→    this.requestTimeout = 10000; // 10 seconds
    20→
    21→    this.setupAnelNamespace();
    22→
    23→    debug('ANEL Connector initialized, waiting for runner connection');
    24→  }
    25→
    26→  setupAnelNamespace() {
    27→    // Setup namespace for anel-runner to connect to
    28→    this.anelNamespace = this.io.of('/runner-anel');
    29→
    30→    this.anelNamespace.on('connection', (socket) => {
    31→      this.isRunnerConnected = true;
    32→      this.runnerSocket = socket;
    33→      debug('ANEL runner connected: %s', socket.id);
    34→
    35→      // Emit debug event
    36→      this.emitDebugEvent('runner_connected', {
    37→        runnerId: socket.id,
    38→        timestamp: Date.now()
    39→      });
    40→
    41→      socket.on('disconnect', () => {
    42→        this.isRunnerConnected = false;
    43→        this.runnerSocket = null;
    44→        debug('ANEL runner disconnected: %s', socket.id);
    45→
    46→        // Emit debug event
    47→        this.emitDebugEvent('runner_disconnected', {
    48→          runnerId: socket.id,
    49→          timestamp: Date.now()
    50→        });
    51→      });
    52→    });
    53→  }
    54→
    55→  async getState(unit) {
    56→    const startTime = Date.now();
    57→
    58→    try {
    59→      debug('Getting state for unit: %s (%s)', unit.id, this.getHostForUnit(unit));
    60→
    61→      // Check if runner is connected
    62→      if (!this.isRunnerConnected || !this.runnerSocket) {
    63→        const error = 'ANEL runner not connected';
    64→        debug('getState failed: %s', error);
    65→        return {
    66→          success: false,
    67→          state: -1,
    68→          error: error,
    69→          unitType: this.type
    70→        };
    71→      }
    72→
    73→      // Build request
    74→      const request = this.buildRequest(unit, 'getState');
    75→
    76→      // Send request with timeout
    77→      const response = await this.sendRequestWithTimeout('executeCommand', request);
    78→
    79→      if (response.success) {
    80→        debug('getState success for unit: %s, state: %d', unit.id, response.state);
    81→
    82→        return {
    83→          success: true,
    84→          state: response.state,
    85→          unitType: this.type,
    86→          host: request.ip,
    87→          port: request.port,
    88→          timestamp: Date.now()
    89→        };
    90→      } else {
    91→        debug('getState failed for unit: %s, error: %s', unit.id, response.error);
    92→        return {
    93→          success: false,
    94→          state: -1,
    95→          error: response.error,
    96→          unitType: this.type
    97→        };
    98→      }
    99→
   100→    } catch (error) {
   101→      const duration = Date.now() - startTime;
   102→      debug('getState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);
   103→
   104→      return {
   105→        success: false,
   106→        state: -1,
   107→        error: error.message,
   108→        unitType: this.type
   109→      };
   110→    }
   111→  }
   112→
   113→  async setState(unit, targetState) {
   114→    const startTime = Date.now();
   115→
   116→    try {
   117→      const stateStr = targetState ? 'on' : 'off';
   118→      debug('Setting state for unit: %s (%s) to %s', unit.id, this.getHostForUnit(unit), stateStr);
   119→
   120→      // Check if runner is connected
   121→      if (!this.isRunnerConnected || !this.runnerSocket) {
   122→        const error = 'ANEL runner not connected';
   123→        debug('setState failed: %s', error);
   124→        return {
   125→          success: false,
   126→          state: unit.state, // Keep current state
   127→          error: error,
   128→          unitType: this.type
   129→        };
   130→      }
   131→
   132→      // Build request
   133→      const request = this.buildRequest(unit, 'setState', {
   134→        targetState: targetState ? 1 : 0,
   135→        state: stateStr
   136→      });
   137→
   138→      // Send request with timeout
   139→      const response = await this.sendRequestWithTimeout('executeCommand', request);
