/*!
 * anelConnector.js - ANEL Socket.IO Client Connector
 * Connects to anel-runner microservice via Socket.IO
 */

const debug = require('debug')('mutech:anel-connector');

class AnelConnector {
  constructor(io, db) {
    this.io = io;
    this.db = db;
    this.type = 'anel';

    // Connection state
    this.isRunnerConnected = false;
    this.runnerSocket = null;

    // Configuration
    this.requestTimeout = 10000; // 10 seconds

    this.setupAnelNamespace();

    debug('ANEL Connector initialized, waiting for runner connection');
  }

  setupAnelNamespace() {
    // Setup namespace for anel-runner to connect to
    this.anelNamespace = this.io.of('/runner-anel');

    this.anelNamespace.on('connection', (socket) => {
      this.isRunnerConnected = true;
      this.runnerSocket = socket;
      debug('ANEL runner connected: %s', socket.id);

      // Emit debug event
      this.emitDebugEvent('runner_connected', {
        runnerId: socket.id,
        timestamp: Date.now()
      });

      socket.on('disconnect', () => {
        this.isRunnerConnected = false;
        this.runnerSocket = null;
        debug('ANEL runner disconnected: %s', socket.id);

        // Emit debug event
        this.emitDebugEvent('runner_disconnected', {
          runnerId: socket.id,
          timestamp: Date.now()
        });
      });
    });
  }

  async getState(unit) {
    const startTime = Date.now();

    try {
      debug('Getting state for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'ANEL runner not connected';
        debug('getState failed: %s', error);
        return {
          success: false,
          state: -1,
          error: error,
          unitType: this.type
        };
      }

      // Build request
      const request = this.buildRequest(unit, 'getState');

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('executeCommand', request);

      if (response.success) {
        debug('getState success for unit: %s, state: %d', unit.id, response.state);

        return {
          success: true,
          state: response.state,
          unitType: this.type,
          host: request.ip,
          port: request.port,
          timestamp: Date.now()
        };
      } else {
        debug('getState failed for unit: %s, error: %s', unit.id, response.error);
        return {
          success: false,
          state: -1,
          error: response.error,
          unitType: this.type
        };
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      debug('getState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);

      return {
        success: false,
        state: -1,
        error: error.message,
        unitType: this.type
      };
    }
  }

  async setState(unit, targetState) {
    const startTime = Date.now();

    try {
      const stateStr = targetState ? 'on' : 'off';
      debug('Setting state for unit: %s (%s) to %s', unit.id, this.getHostForUnit(unit), stateStr);

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'ANEL runner not connected';
        debug('setState failed: %s', error);
        return {
          success: false,
          state: unit.state, // Keep current state
          error: error,
          unitType: this.type
        };
      }

      // Build request
      const request = this.buildRequest(unit, 'setState', {
        targetState: targetState ? 1 : 0,
        state: stateStr
      });

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('executeCommand', request);

      if (response.success) {
        const finalState = targetState ? 1 : 0;
        debug('setState success for unit: %s, state: %d, duration: %dms', unit.id, finalState, response.duration || 0);

        return {
          success: true,
          state: finalState,
          unitType: this.type,
          host: request.ip,
          port: request.port,
          duration: response.duration,
          timestamp: Date.now()
        };
      } else {
        debug('setState failed for unit: %s, error: %s', unit.id, response.error);
        return {
          success: false,
          state: unit.state, // Keep current state on failure
          error: response.error,
          unitType: this.type
        };
      }

    } catch (error) {
      const duration = Date.now() - startTime;
      debug('setState exception for unit: %s, error: %s, duration: %dms', unit.id, error.message, duration);

      return {
        success: false,
        state: unit.state, // Keep current state on failure
        error: error.message,
        unitType: this.type
      };
    }
  }

  // Get device information
  async getDeviceInfo(unit) {
    try {
      debug('Getting device info for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      if (!this.isRunnerConnected || !this.runnerSocket) {
        return {
          success: false,
          error: 'ANEL runner not connected'
        };
      }

      const request = this.buildRequest(unit, 'getDeviceInfo');

      const response = await this.sendRequestWithTimeout('executeCommand', request);

      debug('getDeviceInfo result for unit: %s, success: %s', unit.id, response.success);

      return response;

    } catch (error) {
      debug('getDeviceInfo exception for unit: %s, error: %s', unit.id, error.message);
      return {
        success: false,
        error: error.message
      };
    }
  }

  // Build structured request object for ANEL operations
  buildRequest(unit, operation, additionalParams = {}) {
    const baseRequest = {
      unitId: unit.id,
      operation: operation,
      ip: this.getHostForUnit(unit),
      port: parseInt(unit.args?.port || '0'),
      user: this.getCredential(unit, 'user'),
      password: this.getCredential(unit, 'password'),
      timeout: 5000
    };

    // Merge any additional parameters
    return { ...baseRequest, ...additionalParams };
  }

  // Get credential with fallback to environment variables
  getCredential(unit, credentialType) {
    // First try unit-specific credential
    const unitCredential = unit.args?.[credentialType];
    if (unitCredential) {
      return unitCredential;
    }

    // Fallback to environment variables
    if (credentialType === 'user') {
      return process.env.ANEL_DEFAULT_USER || null;
    } else if (credentialType === 'password') {
      return process.env.ANEL_DEFAULT_PASSWORD || null;
    }

    return null;
  }

  // Send request to runner with timeout
  sendRequestWithTimeout(event, data) {
    return new Promise((resolve, reject) => {
      if (!this.runnerSocket) {
        reject(new Error('ANEL runner not connected'));
        return;
      }

      // Set timeout
      const timeoutId = setTimeout(() => {
        debug('Request timeout for event: %s, data: %o', event, data);
        this.emitDebugEvent('request_timeout', {
          event: event,
          data: data,
          timeout: this.requestTimeout,
          timestamp: Date.now()
        });
        reject(new Error(`Timeout waiting for ANEL runner response (${this.requestTimeout}ms)`));
      }, this.requestTimeout);

      // Send request
      this.runnerSocket.emit(event, data, (response) => {
        clearTimeout(timeoutId);

        if (!response) {
          reject(new Error('No response from ANEL runner'));
          return;
        }

        // Pass through response as-is
        resolve(response);
      });
    });
  }

  // Get host for unit (unit.host first, fallback to unit.ip)
  getHostForUnit(unit) {
    if (unit.host && unit.host !== '#nohost') {
      return unit.host;
    }
    return unit.ip || 'unknown-host';
  }

  // Emit debug event to debug namespace
  emitDebugEvent(eventType, data) {
    try {
      this.io.of('/debug').emit('anelEvent', {
        type: eventType,
        data: data,
        timestamp: Date.now()
      });
    } catch (error) {
      // Don't let debug event emission fail the main operation
      debug('Error emitting debug event: %s', error.message);
    }
  }

  // Check if runner is connected
  isConnected() {
    return this.isRunnerConnected;
  }

  // Get connector information
  getConnectorInfo() {
    return {
      type: this.type,
      status: this.isRunnerConnected ? 'connected' : 'waiting',
      capabilities: ['getState', 'setState', 'getDeviceInfo'],
      description: 'ANEL Socket.IO connector - communicates with anel-runner microservice',
      runnerConnected: this.isRunnerConnected,
      requestTimeout: this.requestTimeout,
      method: 'socket.io-client',
      protocol: 'UDP via anel-manager library',
      credentialSources: ['unit.args', 'environment variables'],
      environmentVariables: {
        user: 'ANEL_DEFAULT_USER',
        password: 'ANEL_DEFAULT_PASSWORD'
      }
    };
  }

  // Disconnect (cleanup)
  disconnect() {
    debug('ANEL Connector disconnecting');

    if (this.anelNamespace) {
      // Close namespace connections
      this.anelNamespace.disconnectSockets(true);
    }

    this.isRunnerConnected = false;
    this.runnerSocket = null;
  }
}

module.exports = AnelConnector;

