/**
 * ANEL Manager - Main Manager Class
 * 
 * Global command queue manager for ANEL power outlet control
 */

const EventEmitter = require('events');
const ANELConnection = require('./connection');
const { setPowerState, getPowerState } = require('./commands');
const { parseStatusResponse } = require('./protocol');
const { createError } = require('./errors');

class ANELManager extends EventEmitter {
  constructor() {
    super();

    // Load configuration from environment
    this.config = {
      commandDelay: parseFloat(process.env.ANEL_COMMAND_DELAY) || 0.5,
      sendPort: parseInt(process.env.ANEL_UDP_SEND_PORT) || 9975,
      receivePort: parseInt(process.env.ANEL_UDP_RECEIVE_PORT) || 9977,
      defaultUser: process.env.ANEL_DEFAULT_USER || 'root',
      defaultPassword: process.env.ANEL_DEFAULT_PASSWORD || 'brotwurst',
      connectionTimeout: parseInt(process.env.ANEL_CONNECTION_TIMEOUT) || 5000
    };

    // Global command queue
    this.commandQueue = [];
    this.isProcessing = false;
    this.queueProcessor = null;

    // Connection management
    this.connection = null;
    this.isStarted = false;

    // Start connection and queue processor
    this.start();
  }

  /**
   * Initialize the manager
   */
  async start() {
    if (this.isStarted) return;

    try {
      // Initialize connection
      this.connection = new ANELConnection(this.config);

      // Listen for status messages
      this.connection.on('message', (msg, rinfo) => {
        this.handleStatusMessage(msg, rinfo);
      });

      await this.connection.start();

      // Start queue processor
      this.startQueueProcessor();

      this.isStarted = true;
      console.log('ANEL Manager started');
    } catch (error) {
      console.error('Failed to start ANEL Manager:', error);
      throw error;
    }
  }

  /**
   * Start the global command queue processor
   */
  startQueueProcessor() {
    if (this.queueProcessor) return;

    this.queueProcessor = setInterval(() => {
      this.processQueue();
    }, this.config.commandDelay * 1000);
  }

  /**
   * Process the next command in the queue
   */
  async processQueue() {
    if (this.isProcessing || this.commandQueue.length === 0) {
      return;
    }

    this.isProcessing = true;

    try {
      const queueItem = this.commandQueue.shift();
      const { commandFunction, args, resolve, reject } = queueItem;

      try {
        await commandFunction(...args);
        resolve();
      } catch (error) {
        reject(error);
      }
    } catch (error) {
      console.error('Queue processing error:', error);
    } finally {
      this.isProcessing = false;
    }
  }

  /**
   * Add a command to the queue
   */
  queueCommand(commandFunction, args) {
    return new Promise((resolve, reject) => {
      this.commandQueue.push({
        commandFunction,
        args,
        resolve,
        reject,
        timestamp: Date.now()
      });
    });
  }

  /**
   * Execute command immediately (fast lane)
   */
  async executeImmediate(commandFunction, args) {
    return await commandFunction(...args);
  }

  /**
   * Handle incoming status messages
   */
  handleStatusMessage(msg, rinfo) {
    try {
      const status = parseStatusResponse(msg);
      if (status) {
        // Emit individual port status events
