async def handle_anel_broadcast(status: dict):
    """Handle ANEL device status broadcast"""
    ip = status['ip']

    for port_info in status['ports']:
        port = port_info['port']
        state = port_info['state']

        # Update cache
        device_status_cache[(ip, port)] = {
            'state': state,
            'name': port_info['name'],
            'timestamp': status['timestamp']
        }

