            "state": info['state'],
            "name": info['name'],
            "timestamp": info['timestamp']
        }
        for (cached_ip, port), info in device_status_cache.items()
        if cached_ip == ip
    ]

    if not ports:
        raise HTTPException(status_code=404, detail="No data for device")

    return {
        "ip": ip,
        "ports": ports
    }


