/* Device Badge */
.device-badge {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  padding: 0.5rem 0.75rem;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: all 0.2s;
  overflow: hidden;
  min-width: 120px;
  border: 2px solid;
}

.device-badge:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 8px rgba(0,0,0,0.2);
}

/* Progress bar - drains from 100% to 0% */
.progress-top-border {
  position: absolute;
  top: 0;
  left: 0;
  height: 4px;
  background: rgba(255,255,255,0.8);
  transition: width 1s linear;
}

.cooldown-100 .progress-top-border { width: 100%; }
.cooldown-75 .progress-top-border { width: 75%; }
.cooldown-50 .progress-top-border { width: 50%; }
.cooldown-25 .progress-top-border { width: 25%; }
.cooldown-0 .progress-top-border { width: 0%; }

/* Device States */
.device-error {
  background: var(--state-error);
  color: white;
  border-color: #b02a37;
}

.device-off {
  background: var(--state-off);
  color: white;
  border-color: #565e64;
}

.device-on {
  background: var(--state-on);
  color: white;
  border-color: #146c43;
}

.device-cooling {
  background: var(--state-cooling);
  color: #000;
  border-color: #cc9a06;
}

.device-name {
  font-size: 0.85em;
  font-weight: 600;
  text-align: center;
  margin-top: 0.25rem;
}

.device-info {
  font-size: 0.75em;
  opacity: 0.9;
  text-align: center;
}

.device-cooldown {
  font-size: 0.7em;
  opacity: 0.8;
  margin-top: 0.25rem;
}

/* Automation Disabled - Visual Indent + Striped Pattern */
.automation-disabled {
  margin-left: 1.5rem;
  position: relative;
}

.automation-disabled::before {
  content: '';
  position: absolute;
  left: -1rem;
  top: 0;
  bottom: 0;
  width: 4px;
  background: repeating-linear-gradient(
    45deg,
    #dee2e6,
    #dee2e6 5px,
    transparent 5px,
    transparent 10px

