   826→
   827→    function openDeviceAccordion(deviceElement, artworkId, deviceId) {
   828→      // Close current accordion if open
   829→      if (currentOpenAccordion && currentOpenAccordion !== artworkId) {
   830→        closeAccordion(currentOpenAccordion);
   831→      }
   832→
   833→      // Remove active class from previous device
   834→      if (currentActiveDevice) {
   835→        currentActiveDevice.classList.remove('active');
   836→      }
   837→
   838→      // Add active class to clicked device
   839→      deviceElement.classList.add('active');
   840→      currentActiveDevice = deviceElement;
   841→
   842→      const accordion = document.getElementById('accordion-' + artworkId);
   843→      const device = deviceData[deviceId];
   844→
   845→      if (device) {
   846→        // Update accordion content
   847→        document.getElementById('accordion-title-' + artworkId).textContent = device.name;
   848→        document.getElementById('device-host-' + artworkId).textContent = device.host;
   849→        document.getElementById('device-type-' + artworkId).textContent = device.type;
   850→        document.getElementById('device-state-' + artworkId).textContent = device.state;
   851→
   852→        const cooldownEl = document.getElementById('device-cooldown-' + artworkId);
   853→        if (cooldownEl) {
   854→          cooldownEl.textContent = device.cooldown !== '-' ? device.cooldown + ' remaining' : 'Ready';
   855→        }
   856→      }
   857→
   858→      // Open accordion
   859→      accordion.classList.add('open');
   860→      currentOpenAccordion = artworkId;
   861→    }
   862→
   863→    function closeAccordion(artworkId) {
   864→      const accordion = document.getElementById('accordion-' + artworkId);
   865→      accordion.classList.remove('open');
   866→
   867→      // Remove active class from device
   868→      if (currentActiveDevice) {
   869→        currentActiveDevice.classList.remove('active');
   870→        currentActiveDevice = null;
   871→      }
   872→
   873→      if (currentOpenAccordion === artworkId) {
   874→        currentOpenAccordion = null;
   875→      }
   876→    }
