   890→    // Close accordion when clicking outside
   891→    document.addEventListener('click', function(event) {
   892→      if (currentOpenAccordion &&
   893→          !event.target.closest('.device-accordion') &&
   894→          !event.target.closest('.device-badge')) {
   895→        closeAccordion(currentOpenAccordion);
   896→      }
   897→    });
